<"'!doctype html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>Set up mobile banking · Harbour</title><link rel="stylesheet" href="tokens.css"><script>const q=new URLSearchParams(location.search);document.documentElement.dataset.theme=q.get('"'theme')|| (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');</script><link rel=\"stylesheet\" href=\"styles.css\"><script src=\"fixtures.js\" defer></script><script src=\"app.js\" defer></script></head><body><div id=\"app\"></div></body></html>
