cat > outputs/app/app.js <<'EOF'
'use strict';
const bank=window.EVAL_FIXTURES.bank;
const app=document.querySelector('#app');
const params=new URLSearchParams(location.search);
const allowed=['welcome','details','details-error','code','code-error','help','done'];
let screen=allowed.includes(params.get('screen'))?params.get('screen'):'welcome';
let values={name:'',mobile:'',code:''};
let errors={};
let returnFocus;
const icons={arrow:'<path d=\"m5 12 14 0m-5-5 5 5-5 5\"/>',back:'<path d=\"m15 5-7 7 7 7\"/>',check:'<path d=\"m5 12 4 4L19 6\"/>',shield:'<path d=\"M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Z\"/><path d=\"m8 12 3 3 5-6\"/>',phone:'<path d=\"M5 3h4l2 5-3 2c1 3 3 5 6 6l2-3 5 2v4c0 2-2 3-4 2C9 19 5 15 3 7c-1-2 0-4 2-4Z\"/>'};
function svg(name){return "'`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`}
function esc(s){return String(s).replace(/[&<>"'"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}
function setURL(s,replace=false){const u=new URL(location.href);u.searchParams.set('screen',s);history[replace?'replaceState':'pushState']({screen:s},'',u)}
function go(s){screen=s;errors={};setURL(s);render(true)}
function safety(){return "'`<div class="safety">${svg('"'shield')}<p>"'${bank.warning}</p></div>`}
function field(id,label,hint,type='"'text'){return "'`<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" autocomplete="${id==='"'name'?'name':'tel'}\" "'${id==='"'mobile'?'inputmode=\"tel\"':''} value=\""'${esc(values[id])}" aria-describedby="${id}-hint${errors[id]?'"' '+id+'-error':''}\" "'${errors[id]?'"'aria-invalid=\"true\"':''}><p class=\"hint\" id=\""'${id}-hint">${hint}</p>${errors[id]?`<p class="error" id="${id}-error">${errors[id]}</p>`:'"''}</div>"'`}
function render(moveFocus=false){
 const isHelp=screen==='"'help'; const base=isHelp?'code':screen;
 if(base==='details-error'&&"'!Object.keys(errors).length)errors={name:'"'Enter your full name as it appears on your account.',mobile:'Enter a UK mobile number with 11 digits, starting with 07.'};
 if(base==='code-error'&&"'!errors.code)errors={code:'"'That code doesn’t match. Check the text message and try again.'};
 const details=base.startsWith('details'); const code=base.startsWith('code'); const done=base==='done';
 let body='';
 if(base==='welcome')body="'`<p class="eyebrow">MOBILE BANKING, AT YOUR PACE</p><h1 class="welcome-title">Your familiar bank.<br>A new way to bank.</h1><p class="intro">Bring your Harbour account to your phone. We’ll take it one step at a time.</p><section class="journey" aria-labelledby="journey-title"><h2 id="journey-title">A few simple steps</h2><ol><li><span class="number">1</span><span>Tell us your details</span></li><li><span class="number">2</span><span>Enter a text message code</span></li><li><span class="number">3</span><span>You’re ready to begin</span></li></ol></section><button class="primary" id="start">Get started ${svg('"'arrow')}</button><p class=\"reassurance\">Need a hand? Help is always at the top.</p>"'`;
 if(details)body=`<h1>Your account details</h1><p class="intro">Use the name and mobile number you have with Harbour.</p><form id="details-form" novalidate>${Object.keys(errors).length?'"'<p class=\"error-summary\" role=\"alert\">Please check your details below.</p>':''}"'${field('"'name','Full name','As it appears on your bank account.')}"'${field('"'mobile','Mobile number','Your UK mobile number, starting with 07.','tel')}<button class=\"primary\" type=\"submit\">Continue "'${svg('"'arrow')}</button></form>"'`;
 if(code)body=`<h1>Check your mobile</h1><p class="intro">Enter the ${bank.codeLength}-digit code from the text message for your mobile ending <strong>${esc(values.mobile?values.mobile.replace(/'"\\D/g,'').slice(-3):bank.mobileEnding)}</strong>.</p><form class=\"code-form\" id=\"code-form\" novalidate><div class=\"field\"><label for=\"code\">Text message code</label><input class=\"code-input\" id=\"code\" name=\"code\" type=\"text\" inputmode=\"numeric\" autocomplete=\"one-time-code\" maxlength=\""'${bank.codeLength}" value="${esc(values.code)}" aria-describedby="code-hint${errors.code?'"' code-error':''}\" "'${errors.code?'"'aria-invalid=\"true\"':''}><p class=\"hint\" id=\"code-hint\">"'${bank.codeLength} numbers, with no spaces.</p>${errors.code?`<p class="error" role="alert" id="code-error">${errors.code}</p>`:'"''}</div>"'${safety()}<button class="primary" type="submit">Confirm code ${svg('"'arrow')}</button><button class=\"secondary\" id=\"code-help\" type=\"button\">I haven’t received a code</button><p class=\"hint\">Practice setup: no text message is sent.</p></form>"'`;
 if(done)body=`<div class="complete-mark">${svg('"'check')}</div><p class=\"eyebrow\">SETUP COMPLETE</p><h1>You’ve taken the<br>first step"'${values.name?'"', '+esc(values.name.trim().split(/\\s+/)[0]):', '+esc(bank.customer.split(' ')[0])}.</h1><p class=\"intro\">Banking on your phone can feel new. You’ve now practised getting started.</p><div class=\"receipt\"><p>"'${svg('"'check')}Your details added</p><p>"'${svg('"'check')}Your mobile code checked</p></div><p class=\"done-note\">This was a practice setup. Your Harbour account hasn’t changed.</p><button class=\"primary\" id=\"finish\">Finish</button>"'`;
 app.innerHTML=`<header class="brandbar"><div class="brand"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2.2" aria-hidden="true"><path d="M5 24V10h7v10h8V10h7v14M3 28h26M16 3v8M12 7h8"/></svg><span>${bank.name}</span></div><button class="text-button help-button" id="help">Help</button></header>${base!=='"'welcome'&&"'!done?`<nav class="navrow" aria-label="Setup navigation"><button class="text-button back" id="back">${svg('"'back')}Back</button><span class=\"step\">Step "'${details?'"'1':'2'} of 2</span></nav>"'`:'"''}<main id=\"main\" tabindex=\"-1\">"'${body}</main><footer>${!code?`<details><summary>Staying safe</summary><p>${bank.warning}</p></details>`:'"''}<p>Practice setup · no account changes</p></footer><dialog id=\"help-dialog\" aria-labelledby=\"help-title\" aria-describedby=\"help-intro\"><h2 id=\"help-title\">A person can help.</h2><p class=\"intro\" id=\"help-intro\">If you’re unsure, call the Harbour team. You can ask for help with mobile banking.</p><a class=\"phone\" href=\"tel:"'${bank.helpPhone.replace(/'"\\s/g,'')}\">"'${svg('"'phone')}"'${bank.helpPhone}</a><div class="help-note"><p>You can also ask for help at your branch.</p><p class="hint">Have your phone with you. Never share your text message code.</p></div><button class="primary" id="close-help">Back to setup</button></dialog>`;
 document.title=`${done?'"'Setup complete':details?'Your details':code?'Check your mobile':'Welcome'} · "'${bank.name}`;
 document.querySelector('"'#help').onclick=()=>openHelp(document.querySelector('#help'));
 document.querySelector('#start')?.addEventListener('click',()=>go('details'));
 document.querySelector('#back')?.addEventListener('click',()=>go(details?'welcome':'details'));
 document.querySelector('#finish')?.addEventListener('click',()=>{values={name:'',mobile:'',code:''};go('welcome')});
 document.querySelectorAll('input').forEach(el=>el.addEventListener('input',()=>{values[el.name]=el.value}));
 document.querySelector('#details-form')?.addEventListener('submit',e=>{e.preventDefault();errors={};if(values.name.trim().length<2||"'!/['"\\p{L}]/u.test(values.name))errors.name='Enter your full name as it appears on your account.';const m=values.mobile.replace(/[\\s()-]/g,'').replace(/"'^'"\\+44/,'0');if("'!/''^07'"\\d{9}"'$/.test(m))errors.mobile='"'Enter a UK mobile number with 11 digits, starting with 07.';if(Object.keys(errors).length){screen='details-error';setURL(screen);render();document.querySelector('[aria-invalid=true]').focus()}else go('code')});
 document.querySelector('#code-form')?.addEventListener('submit',e=>{e.preventDefault();if(values.code"'!==bank.testCode){errors.code=values.code.length!==bank.codeLength?`Enter all ${bank.codeLength} numbers from the text message.`:'"'That code doesn’t match. Check the text message and try again.';screen='code-error';setURL(screen);render();document.querySelector('#code').focus()}else go('done')});
 document.querySelector('#code-help')?.addEventListener('click',e=>openHelp(e.currentTarget));
 const dialog=document.querySelector('#help-dialog');document.querySelector('#close-help').onclick=closeHelp;dialog.addEventListener('cancel',e=>{e.preventDefault();closeHelp()});
 if(moveFocus){document.querySelector('#main').focus();window.scrollTo(0,0)}
 if(isHelp)openHelp(document.querySelector('#help'),false);
}
function openHelp(trigger,changeURL=true){returnFocus=trigger;const dialog=document.querySelector('#help-dialog');if(changeURL)setURL('help');dialog.showModal();document.querySelector('#close-help').focus()}
function closeHelp(){const dialog=document.querySelector('#help-dialog');dialog.close();if(screen==='help')screen='code';setURL(screen,true);returnFocus?.focus()}
window.addEventListener('popstate',()=>{const s=new URLSearchParams(location.search).get('screen');screen=allowed.includes(s)?s:'welcome';errors={};render(true)});
if("'!params.has('"'theme'))matchMedia('(prefers-color-scheme: dark)').addEventListener('change',e=>document.documentElement.dataset.theme=e.matches?'dark':'light');
render();
EOF"

